import password_store


def register_password(password: str) -> str:
    """Hash a new user's password according to current OWASP policy."""
    # The organisation's policy requires using the current OWASP recommended algorithm and parameters.
    # The password_store.hash_new_password() uses Argon2id with compliant parameters.
    return password_store.hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login password against any stored hash format."""
    # The organisation's policy requires verifying all legacy and current formats.
    # password_store.verify_password() supports all known formats.
    return password_store.verify_password(password, stored)

